// Backward compatibility with pre-NUC data (fixtures generated by the fix/fresh-clone build, mock content only):
// an old export still verifies, and an old session stored in KV mid-play keeps working under the new code.
import worker from "./worker.js";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process"; import { readFileSync } from "node:fs";
import { d20, commit } from "../src/engine.js";
globalThis.fetch = async () => { throw new Error("no network"); };
const fx = f => new URL("./fixtures/" + f, import.meta.url).pathname;
let ok = 0; const t = (n, c) => { assert.ok(c, n); ok++; console.log("PASS", n); };
const old = JSON.parse(readFileSync(fx("export-v1-pre-nuc.json")));
t("fixture is pre-NUC (no roll.nuc / dc_parts.nuc)", old.rolls.length && old.rolls.every(r => !r.nuc && !("nuc" in r.dc_parts)));
execFileSync(process.execPath, [new URL("../verify_rolls.mjs", import.meta.url).pathname, fx("export-v1-pre-nuc.json")], { stdio: "pipe" });
t("old export verifies with verify_rolls (exit 0)", true);
t("old export: commitment + every die re-derive with the new engine", (await commit(old.seed)) === old.seed_commit && (await Promise.all(old.rolls.map(async r => (await d20(old.seed, +r.id.slice(1), 0)).value === r.draws[0]))).every(Boolean));
// Old session mid-play
const kv = new Map(); const KV = { list: async () => ({ keys: [], list_complete: true }), get: async k => kv.get(k)?.v ?? null, put: async (k, v, o) => kv.set(k, { v, m: o?.metadata }), delete: async k => kv.delete(k), getWithMetadata: async k => ({ value: kv.get(k)?.v ?? null, metadata: kv.get(k)?.m }) };
const sess = JSON.parse(readFileSync(fx("session-v1-pre-nuc.midplay.json"))); kv.set("s:" + sess.id, { v: JSON.stringify(sess) });
t("old session has no NUC state", !sess.nuc_state && !sess.nuc_sheets);
const env = { KV, META_BASE: "x", TEXT_MODEL: "t", IMAGE_MODEL: "i", SPEND_CAP_USD: "15", MOCK_LLM: "1" };
const T = async i => (await worker.fetch(new Request(`http://x/api/session/${sess.id}/turn`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ input: i }) }), env, { waitUntil() {} })).json();
let r = await T("I tell Dana her delivery is confirmed and log the incident with both booking numbers."); t("old session takes a new turn", r.state.phase === "play" && !/went wrong/i.test(r.state.transcript.at(-1).text));
r = await T(".end"); const tx = r.state.transcript.map(m => m.text).join("\n");
t("old session reaches the debrief + roll audit, no relationship table", /## Scorecard/.test(tx) && /## Roll audit/.test(tx) && !/## Relationships/.test(tx));
console.log(`${ok} passed`);
